        ops=set()
        for i in range(n):
            for j in range(n):
                if i!=j:
                    ops.add(('d',abs(xs[i]-xs[j])))
                    if xs[i]%xs[j]==0 and xs[i]//xs[j]>1: ops.add(('r',xs[i]//xs[j]))
